// Definition for a binary tree node.
class Node {
    int data;
    Node left;
    Node right;
    Node(int data) { this.data = data; }
}

public void preorder(Node root) {
    if (root == null) return;          // base case: nothing to visit
    System.out.print(root.data + " "); // 1) visit the node FIRST
    preorder(root.left);               // 2) left subtree
    preorder(root.right);              // 3) right subtree
}

public void preorder(Node root) {
    if (root == null) return;
    Deque<Node> stack = new ArrayDeque<>();
    stack.push(root);
    while (!stack.isEmpty()) {
        Node node = stack.pop();
        System.out.print(node.data + " ");      // visit on pop (root-first)
        if (node.right != null) stack.push(node.right); // RIGHT first...
        if (node.left != null) stack.push(node.left);   // ...LEFT last → popped first
    }
}

