def preorder(root: Node) -> None:
    if root is None:
        return
    stack = [root]
    while stack:
        node = stack.pop()
        print(node.data, end=' ')          # visit on pop (root-first)
        if node.right is not None:
            stack.append(node.right)       # RIGHT first...
        if node.left is not None:
            stack.append(node.left)        # ...LEFT last -> popped first

